mapper.select:
SELECT t.asgn_id,t.dev_id,t.work_day_qty,t.rglr_tm_qty,t.ovtm_tm_qty,t.mth_work_day_qty
FROM bill.dspch_atnd t
WHERE t.work_ym=#{scope.month} AND t.prj_id=#{scope.projectId} AND t.dev_id=#{item.dev_id}

SELECT EXISTS (
  SELECT 1 FROM bill.bill_dtl d
  JOIN bill.bill b ON b.bill_id=d.bill_id
  JOIN asgn.asgn a ON a.asgn_id=d.asgn_id
  WHERE b.bill_stts_cd='CONFIRM' AND d.work_ym=#{scope.month}
    AND a.prj_id=#{scope.projectId} AND a.dev_id=#{item.dev_id}
)
